GATE_SOURCE = 'import json\nimport subprocess\nimport sys\n\nold_container, old_image = sys.argv[1:]\nformat_metadata = (\'{"id":{{json .Id}},"image":{{json .Image}},\'\n                   \'"running":{{json .State.Running}},\'\n                   \'"service":{{json (index .Config.Labels "com.docker.compose.service")}},\'\n                   \'"configured_image":{{json .Config.Image}},"name":{{json .Name}}}\')\n\ndef command(args, include_stderr=False, **kwargs):\n    result = subprocess.run(args, capture_output=True, text=True, **kwargs)\n    if result.returncode:\n        raise RuntimeError("gateway cutover inspection failed; admission remains fenced")\n    return (result.stdout + (result.stderr if include_stderr else "")).strip()\n\ncurrent = json.loads(command([\'docker\', \'inspect\', \'yleum-prod-gw\', \'--format\', format_metadata]))\nexpected_image = command([\'docker\', \'image\', \'inspect\', \'omnia-gateway:prod\', \'--format\', \'{{.Id}}\'])\nif not (current[\'running\'] is True and current[\'id\'] != old_container\n        and current[\'image\'] == expected_image\n        and current[\'configured_image\'] == \'omnia-gateway:prod\'\n        and current[\'service\'] == \'gateway\'):\n    raise RuntimeError("gateway replacement identity is not confirmed; admission remains fenced")\nrunning = command([\'docker\', \'ps\', \'--no-trunc\', \'--format\', \'{{.ID}}\']).splitlines()\nif old_container in running:\n    raise RuntimeError("previous gateway container is still running; admission remains fenced")\nfor container in running:\n    if container == current[\'id\']:\n        continue\n    item = json.loads(command([\'docker\', \'inspect\', container, \'--format\', format_metadata]))\n    if (item[\'service\'] == \'gateway\' or item[\'image\'] == old_image\n            or item[\'configured_image\'].startswith(\'omnia-gateway:\')\n            or item[\'name\'] in (\'/yleum-prod-gw\', \'/omnia-prod-gw\')):\n        raise RuntimeError("another gateway writer is running; admission remains fenced")\nfor image in {old_image, expected_image}:\n    ancestors = command([\'docker\', \'ps\', \'--no-trunc\', \'--filter\', \'ancestor=\' + image,\n                         \'--format\', \'{{.ID}}\']).splitlines()\n    if any(container != current[\'id\'] for container in ancestors):\n        raise RuntimeError("another gateway image writer is running; admission remains fenced")\nlogs = command([\'docker\', \'logs\', current[\'id\']], include_stderr=True)\nif \'startup.postgres_unavailable\' in logs:\n    raise RuntimeError("new gateway started without its database; admission remains fenced")\n# Query the new container\'s configured gateway pool, not the API\'s DB connection.\n# Its live /health also verifies that the serving process has initialized a pool.\nprogram = \'\'\'import asyncio, json, urllib.request\nfrom yleum_gateway.core.db import init_pool, get_pool, close_pool\nasync def verify():\n    try:\n        with urllib.request.urlopen("http://127.0.0.1:8001/health", timeout=10) as response:\n            if response.status != 200 or json.load(response).get("status") != "ok":\n                raise RuntimeError("gateway health failed")\n        await init_pool()\n        async with get_pool().acquire() as connection, connection.transaction(readonly=True):\n            if not await connection.fetchval("SELECT EXISTS(SELECT 1 FROM alembic_version)"):\n                raise RuntimeError("migration marker missing")\n            if not await connection.fetchval("SELECT to_regclass(\'public.usage_settlements\') IS NOT NULL"):\n                raise RuntimeError("settlement table missing")\n            # Feature gate accepts later migration heads without assuming head is forever 0074.\n            await connection.fetch("SELECT id,user_id,billing_account_id,provider_scope,provider_request_id,receipt_hash,usage_id,wallet_charge_id,status FROM usage_settlements LIMIT 0")\n            # Alembic\'s check naming convention expands explicitly named checks.\n            # Require the actual validated definitions, independent of their names.\n            constraints = await connection.fetch("SELECT c.contype::text AS kind,c.convalidated AS validated,pg_get_constraintdef(c.oid) AS definition,ARRAY(SELECT a.attname::text FROM unnest(c.conkey) WITH ORDINALITY AS k(attnum,n) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.attnum ORDER BY k.n) AS columns FROM pg_constraint c WHERE c.conrelid=\'public.usage_settlements\'::regclass AND c.contype IN (\'u\',\'c\')")\n            receipt_unique = any(row[\'kind\'] == \'u\' and row[\'validated\']\n                and sorted(row[\'columns\']) == [\'provider_request_id\',\'provider_scope\',\'user_id\']\n                for row in constraints)\n            checks = {row[\'definition\'] for row in constraints\n                      if row[\'kind\'] == \'c\' and row[\'validated\']}\n            expected_checks = {\n                "CHECK ((status = ANY (ARRAY[\'settled\'::text, \'free\'::text, \'unpaid\'::text])))",\n                "CHECK (((status = \'settled\'::text) = (wallet_charge_id IS NOT NULL)))",\n            }\n            if not receipt_unique or not expected_checks.issubset(checks):\n                raise RuntimeError("settlement constraints missing")\n    except Exception:\n        raise SystemExit("gateway settlement schema unavailable; admission remains fenced") from None\n    finally:\n        await close_pool()\nasyncio.run(verify())\n\'\'\'\ncommand([\'docker\', \'exec\', \'-i\', current[\'id\'], \'python\', \'-\'], input=program)\nprint("gateway writer retirement, runtime health and settlement schema confirmed")'
INGRESS_SOURCE = '#!/usr/bin/env python3\n"""Owned, reversible nginx admission barrier for the canonical production vhost."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport os\nimport re\nimport stat\nimport subprocess\nimport tempfile\nimport time\nimport urllib.error\nimport urllib.request\nfrom pathlib import Path\n\nVHOST = Path("/etc/nginx/sites-available/yleum.ru")\nMAP = Path("/etc/nginx/conf.d/yleum-generation-drain.conf")\nSTATE = Path("/var/lib/yleum/generation-ingress-drain")\nMARKER = b"# yleum-owned-generation-ingress-drain-v1"\nMAP_BODY = b"""map "$request_method:$uri" $yleum_generation_drain {\n    default 0;\n    ~^POST:/api/projects/[^/]+/generation/cancel$ 0;\n    ~^POST:/api/projects/[^/]+/restorations/[^/]+/cancel$ 0;\n    ~^(POST|PUT|PATCH|DELETE):/api/projects(/|$) 1;\n}\n"""\nRULE = (\n    b"\\n        " + MARKER + b"\\n"\n    b"        if ($yleum_generation_drain) {\\n"\n    b\'            return 503 \\\'{"error":{"code":"generation_draining",\'\n    b\'"message":"Generation admission is temporarily paused"}}\\\';\\n\'\n    b"        }\\n"\n)\n\n\ndef digest(value: bytes) -> str:\n    return hashlib.sha256(value).hexdigest()\n\n\ndef render_vhost(source: bytes) -> bytes:\n    if MARKER in source:\n        raise RuntimeError("unowned ingress marker already exists")\n    matches = list(re.finditer(rb"\\blocation\\s+/api/\\s*\\{", source))\n    if len(matches) != 1:\n        raise RuntimeError("expected exactly one canonical /api/ location")\n    position = matches[0].end()\n    return source[:position] + RULE + source[position:]\n\n\ndef write_atomic(path: Path, content: bytes, mode: int = 0o600) -> None:\n    fd, name = tempfile.mkstemp(prefix=".yleum-drain-", dir=path.parent)\n    try:\n        with os.fdopen(fd, "wb") as stream:\n            stream.write(content)\n        os.chmod(name, mode)\n        os.replace(name, path)\n    finally:\n        if os.path.exists(name):\n            os.unlink(name)\n\n\ndef command(*args: str) -> None:\n    subprocess.run(args, check=True, capture_output=True, timeout=30)\n\n\ndef probe() -> None:\n    # Unauthenticated impossible-project request cannot create paid work even\n    # if the barrier is absent. Only the nginx 503/code is accepted as evidence.\n    request = urllib.request.Request(\n        "https://yleum.ru/api/projects/00000000-0000-0000-0000-000000000000/prompt",\n        data=b"{}",\n        headers={"Content-Type": "application/json"},\n        method="POST",\n    )\n    for attempt in range(5):\n        try:\n            with urllib.request.urlopen(request, timeout=15):\n                pass\n        except urllib.error.HTTPError as exc:\n            try:\n                if exc.code == 503:\n                    try:\n                        raw = exc.read(8193)\n                        body = json.loads(raw) if len(raw) <= 8192 else None\n                    except (ValueError, UnicodeDecodeError):\n                        body = None\n                    if isinstance(body, dict):\n                        error = body.get("error")\n                        if (\n                            isinstance(error, dict)\n                            and error.get("code") == "generation_draining"\n                        ):\n                            return\n                retry = exc.code == 401 and attempt < 4\n            finally:\n                exc.close()\n            if retry:\n                time.sleep(1)\n                continue\n        raise RuntimeError("live ingress admission barrier was not confirmed")\n\n\ndef owned(release: str) -> dict[str, object]:\n    data = json.loads((STATE / "active.json").read_text())\n    if data["release_sha"] != release:\n        raise RuntimeError("ingress drain belongs to another release")\n    if digest(VHOST.read_bytes()) != data["blocked_sha"] or MAP.read_bytes() != MAP_BODY:\n        raise RuntimeError("ingress configuration changed; preserve it and reconcile explicitly")\n    return data\n\n\ndef begin(release: str) -> None:\n    STATE.mkdir(parents=True, exist_ok=True, mode=0o700)\n    if (STATE / "active.json").exists():\n        owned(release)\n        probe()\n        return\n    if MAP.exists():\n        raise RuntimeError("refusing to overwrite an existing ingress map")\n    source = VHOST.read_bytes()\n    blocked = render_vhost(source)\n    mode = stat.S_IMODE(VHOST.stat().st_mode)\n    backup = STATE / (release + ".original.conf")\n    if backup.exists() and backup.read_bytes() != source:\n        raise RuntimeError("existing backup differs; do not overwrite it")\n    write_atomic(backup, source)\n    write_atomic(MAP, MAP_BODY, 0o644)\n    write_atomic(VHOST, blocked, mode)\n    try:\n        command("nginx", "-t")\n    except Exception:\n        write_atomic(VHOST, source, mode)\n        MAP.unlink()\n        raise\n    data = {\n        "release_sha": release,\n        "original_sha": digest(source),\n        "blocked_sha": digest(blocked),\n        "mode": mode,\n    }\n    write_atomic(STATE / "active.json", json.dumps(data, sort_keys=True).encode())\n    # From here onward errors retain the owned state and barrier. No EXIT cleanup.\n    command("systemctl", "reload", "nginx")\n    probe()\n\n\ndef end(release: str) -> None:\n    data = owned(release)\n    source = (STATE / (release + ".original.conf")).read_bytes()\n    if digest(source) != data["original_sha"]:\n        raise RuntimeError("saved ingress configuration checksum changed")\n    blocked = VHOST.read_bytes()\n    mode = int(data["mode"])\n    write_atomic(VHOST, source, mode)\n    MAP.unlink()\n    try:\n        command("nginx", "-t")\n        command("systemctl", "reload", "nginx")\n    except Exception:\n        write_atomic(MAP, MAP_BODY, 0o644)\n        write_atomic(VHOST, blocked, mode)\n        # The old running nginx may still have the barrier. Retain durable state.\n        raise\n    (STATE / "active.json").unlink()\n\n\nif __name__ == "__main__":\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("action", choices=("begin", "check", "end"))\n    parser.add_argument("release_sha")\n    args = parser.parse_args()\n    if not re.fullmatch(r"[0-9a-f]{40}", args.release_sha):\n        parser.error("full release SHA required")\n    if args.action == "begin":\n        begin(args.release_sha)\n    elif args.action == "end":\n        end(args.release_sha)\n    else:\n        owned(args.release_sha)\n        probe()\n    print(json.dumps({"action": args.action, "release_sha": args.release_sha, "ok": True}))\n'
PUBLICATION_SOURCE = '#!/usr/bin/env python3\n"""Read-only publication quiescence gate using the live controller\'s settings."""\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport subprocess\nimport sys\nfrom pathlib import Path\n\n\ndef require_publications_drained(root: Path) -> int:\n    if not root.parent.is_dir() or root.is_symlink():\n        raise RuntimeError("publication storage authority is unavailable")\n    count = 0\n    for path in root.glob("*/publication.json"):\n        try:\n            if path.is_symlink() or path.parent.is_symlink():\n                raise ValueError("unsafe journal path")\n            value = json.loads(path.read_text(encoding="utf-8"))\n            if value["project_id"] != path.parent.name:\n                raise ValueError("journal identity mismatch")\n            history = value["history"]\n            if not isinstance(history, list):\n                raise ValueError("invalid journal history")\n            if history and history[-1]["response"]["phase"] not in {"done", "failed"}:\n                raise ValueError("unfinished or unknown publication")\n            count += 1\n        except (OSError, ValueError, TypeError, KeyError, IndexError) as exc:\n            # No log bodies/project data are emitted, including malformed JSON.\n            raise RuntimeError("publication journals are not quiescent") from exc\n    return count\n\n\ndef live_publication_root() -> Path:\n    processes = set()\n    for service in ("yleum-orchestrator", "omnia-orchestrator"):\n        result = subprocess.run(\n            ["systemctl", "show", service, "--property=MainPID", "--value"],\n            capture_output=True,\n            text=True,\n            timeout=10,\n        )\n        if result.returncode == 0 and result.stdout.strip().isdigit():\n            pid = int(result.stdout.strip())\n            if pid > 0:\n                processes.add(pid)\n    if len(processes) != 1:\n        raise RuntimeError("expected exactly one live controller process")\n    proc = Path("/proc") / str(processes.pop())\n    if b"yleum_orchestrator" not in (proc / "cmdline").read_bytes():\n        raise RuntimeError("controller process identity is unconfirmed")\n    environment = dict(\n        item.decode().split("=", 1)\n        for item in (proc / "environ").read_bytes().split(b"\\0")\n        if b"=" in item\n    )\n    # Changes affect this read-only helper only, never the live process. Settings\n    # resolve the same environment/.env defaults as that controller; no secrets print.\n    os.environ.clear()\n    os.environ.update(environment)\n    os.chdir((proc / "cwd").resolve())\n    sys.path.insert(0, str(Path.cwd() / "src"))\n    from yleum_orchestrator.core.config import get_settings\n\n    return Path(get_settings().cell_state_path).parent / "cell-publications"\n\n\nif __name__ == "__main__":\n    try:\n        count = require_publications_drained(live_publication_root())\n    except Exception:\n        print(\'{"publication_drained":false}\')\n        raise SystemExit(75) from None\n    print(json.dumps({"publication_drained": True, "journals": count}))\n'
HEALTH_PROGRAM = 'import json,os,urllib.request\nexpected="01241329f3b663b34aa5f0799b0f87d80c64cfca"\nassert os.environ.get("OMNIA_RELEASE_SHA")==expected,"API process revision mismatch"\ndef get(url):\n with urllib.request.urlopen(url,timeout=10) as r:\n  assert r.status==200,"health HTTP mismatch"\n  return json.load(r)\nbody=get("https://yleum.ru/api/health")\nassert body.get("status")=="ok" and body.get("release_sha")==expected,"API health mismatch"\nchecks=body.get("checks")\nassert isinstance(checks,dict) and checks and all(v=="ok" for v in checks.values()),"API checks not all green"\ndeps=body.get("dependencies",{})\nfor field in ("worker_release_sha","generation_worker_release_sha","orchestrator_release_sha"):\n assert deps.get(field)==expected,"runtime dependency identity mismatch"\nbilling=deps.get("billing_worker_release_sha")\nassert deps.get("billing_worker")=="ok" and isinstance(billing,str) and billing in (expected,expected[:12]),"billing worker identity mismatch"\nhosts=json.loads(os.environ.get("ORCHESTRATOR_HOSTS") or "[]")\nassert len(hosts)==2 and {h.get("name") for h in hosts}=={"core","commerce"},"both exact controller roles required"\nroles={}\nfor h in hosts:\n role=get(h["url"].rstrip("/")+"/health")\n assert role.get("status")=="ok" and role.get("release_sha")==expected,"controller role health mismatch"\n roles[h["name"]]={"status":"ok","release_sha":expected}\nprint(json.dumps({"status":"ok","release_sha":expected,"checksAllGreen":True,"workerReleaseSHA":expected,"generationWorkerReleaseSHA":expected,"billingWorkerReportedSHA":billing,"controllerRoles":roles}))\n'
"""QA-only guarded finalization of the failed canonical 012 release; no rollout."""
import argparse
import ast
import hashlib
import json
import os
import pwd
import re
import socket
import stat
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path


def require(condition, label):
    if not condition:
        raise RuntimeError(label)


def run(args, data=None, timeout=60):
    result = subprocess.run(args, input=data, text=True, capture_output=True, timeout=timeout)
    require(result.returncode == 0, "subprocess gate failed; captured output remains private")
    return result.stdout.strip()


def private_read(path):
    descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(descriptor, 'rb') as stream:
        metadata = os.fstat(stream.fileno())
        require(stat.S_ISREG(metadata.st_mode) and metadata.st_mode & 0o077 == 0,
                "unsafe evidence file mode or type")
        require(metadata.st_uid in {0, pwd.getpwnam('zeuszcz').pw_uid}, "unsafe evidence owner")
        return stream.read()


def idle_owned(status):
    require(status.get('release_sha') == SHA, "durable fence belongs to another release")
    counts = status.get('active')
    require(isinstance(counts, dict)
            and set(counts) == {'generations', 'operations', 'leases', 'restorations'}
            and all(type(value) is int and value == 0 for value in counts.values())
            and status.get('drained') is True, "active or unresolved work remains")


def prove_failed_final_pool_step(state, canonical_bytes, log_bytes):
    require(state.get('candidate') == SHA and state.get('phase') == 'blocked',
            "original release state mismatch")
    checks = state.get('checks', {})
    require(type(checks.get('canonicalExitCode')) is int and checks['canonicalExitCode'] == 1,
            "original canonical failure must remain recorded")
    require(checks.get('canonicalSourceSHA256') == CANONICAL_SHA256
            and hashlib.sha256(canonical_bytes).hexdigest() == CANONICAL_SHA256,
            "original canonical source changed")
    require(checks.get('expectedGatewayBillingModuleSHA256') == MODULE_SHA256,
            "original billing module identity mismatch")
    require(checks.get('ciRunId') == 36891744309 and checks.get('ciConclusion') == 'success'
            and checks.get('backupExitCode') == 0, "original CI/backup evidence missing")
    source = canonical_bytes.decode()
    gate = source.split("<<'GATEWAY_CUTOVER_PY'\n", 1)[1].split('\nGATEWAY_CUTOVER_PY', 1)[0]
    tree = ast.parse(gate)
    final = next(node for node in tree.body if isinstance(node, ast.Expr)
                 and isinstance(node.value, ast.Call)
                 and isinstance(node.value.func, ast.Name) and node.value.func.id == 'command')
    require([ast.literal_eval(item) for item in final.value.args[0].elts[:3]]
            == ['docker', 'exec', '-i'],
            "canonical final call changed")
    # The exact source's only top-level command() is after every retirement check.
    # Its failure frame establishes that those checks actually completed earlier.
    tail = log_bytes.decode(errors='replace').rsplit('Traceback (most recent call last):', 1)
    require(len(tail) == 2 and re.search(
        rf'File "<stdin>", line {final.lineno}, in <module>', tail[-1]) is not None
        and 'RuntimeError: gateway cutover inspection failed; admission remains fenced' in tail[-1],
        "original failure is not the exact final pool call")
    return {'originalCanonicalExitCode': 1, 'finalPoolCallLine': final.lineno,
            'priorRetirementProof': 'exact canonical source and final-pool traceback',
            'originalLogSHA256': hashlib.sha256(log_bytes).hexdigest()}


def api_python(program):
    return run(['docker', 'exec', '-i', 'yleum-prod-api', 'python', '-'], program)


def fresh_checks():
    require(run(['git', '-C', str(ROOT), 'rev-parse', 'HEAD']) == SHA,
            "Core checkout revision mismatch")
    require(run(['ssh', '-o', 'BatchMode=yes', 'commerce', 'git', '-C', str(ROOT),
                 'rev-parse', 'HEAD']) == SHA, "Commerce checkout revision mismatch")
    require(run(['git', '-C', str(ROOT), 'show', SHA + ':infra/release/deploy-prod.sh'])
            == CANONICAL_SOURCE.rstrip(), "committed canonical source mismatch")
    status = json.loads(run(['docker', 'exec', 'yleum-prod-api', 'python', '-m',
                            'yleum_api.services.generation_deployment_drain', 'status', SHA]))
    idle_owned(status)
    # Only immutable source bytes from the approved candidate implement end/check.
    run(['python3', '-', 'check', SHA], INGRESS_SOURCE)
    health = json.loads(api_python(HEALTH_PROGRAM))
    role_program = (
        'import os; assert os.environ.get("OMNIA_RELEASE_SHA") == ' + repr(SHA)
        + '; print("role revision confirmed")')
    for container in ('yleum-prod-worker', 'yleum-prod-generation-worker'):
        run(['docker', 'exec', '-i', container, 'python', '-'], role_program)
    module_sha = run(['docker', 'exec', 'yleum-prod-gw', 'python', '-c',
                     'import hashlib,importlib.util,pathlib; '
                     's=importlib.util.find_spec("yleum_gateway.services.billing"); '
                     'assert s and s.origin; '
                     'print(hashlib.sha256(pathlib.Path(s.origin).read_bytes()).hexdigest())'])
    require(module_sha == MODULE_SHA256, "actual gateway billing source mismatch")
    # Exact canonical retirement was already proved. No old ID is invented.
    # Recheck every live service/name/tag writer, current image and its ancestry.
    # The unavailable historical image ancestry is explicitly covered only by
    # the immutable original gate progress, not claimed as a fresh inspection.
    current_gate = GATE_SOURCE.replace('old_container, old_image = sys.argv[1:]',
                                     'old_container, old_image = None, None')
    current_gate = current_gate.replace('for image in {old_image, expected_image}:',
                                       'for image in {old_image, expected_image} - {None}:')
    run(['python3', '-'], current_gate)
    core_publication = json.loads(run(['/opt/omnia/apps/orchestrator/.venv/bin/python', '-'],
                                     PUBLICATION_SOURCE))
    commerce_publication = json.loads(run(['ssh', '-o', 'BatchMode=yes', 'commerce',
        'sudo', '/opt/omnia/apps/orchestrator/.venv/bin/python', '-'], PUBLICATION_SOURCE))
    require(core_publication.get('publication_drained') is True
            and commerce_publication.get('publication_drained') is True,
            "both publication roles must be drained")
    idle_owned(json.loads(run(['docker', 'exec', 'yleum-prod-api', 'python', '-m',
        'yleum_api.services.generation_deployment_drain', 'status', SHA])))
    run(['python3', '-', 'check', SHA], INGRESS_SOURCE)
    return {'apiAndRuntimeRoles': health, 'durableFence': status,
            'gatewayBillingModuleSHA256': module_sha,
            'freshWriterAndSemanticSchemaGate': True,
            'publications': {'core': core_publication, 'commerce': commerce_publication}}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--actor', required=True, choices=('root',))
    parser.add_argument('--execute', action='store_true')
    args = parser.parse_args()
    require(os.geteuid() == 0 and pwd.getpwuid(os.geteuid()).pw_name == args.actor,
            "only the explicit root actor may use this helper")
    os.umask(0o077)
    original_path = Path('/tmp/qa-billing-release-state.json')
    original_bytes = private_read(original_path)
    original_hash = hashlib.sha256(original_bytes).hexdigest()
    evidence = prove_failed_final_pool_step(
        json.loads(original_bytes), private_read(Path('/tmp/qa-billing-release-canonical-' + SHA + '.sh')),
        private_read(Path('/tmp/qa-billing-release-deploy.log')))
    lock = ROOT / '.deploy.lock'
    require(not lock.exists() and not lock.is_symlink(), "deployment lock already exists")
    processes = run(['ps', '-eo', 'args']).splitlines()
    require(not any(re.search(r'(^|[/\s])deploy-prod[.]sh(?:\s|$)|docker compose.*build|rsync.*/opt/omnia',
                              line) for line in processes), "another deployment is active")
    lock_bytes = (f'root@{socket.gethostname()} '
                  f'{datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")} {SHA}\n').encode()
    lock_inode = None
    result_path = Path('/tmp/qa-billing-resume-012-' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%f') + '.json')
    result = {'candidate': SHA, 'actor': args.actor, 'originalCanonicalExitCode': 1,
              'originalReleaseStateSHA256': original_hash, 'evidence': evidence,
              'execute': args.execute, 'phase': 'preflight',
              'normalIngressEndConfirmed': False, 'normalDurableEndConfirmed': False}
    descriptor = os.open(result_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY | os.O_NOFOLLOW, 0o600)
    os.close(descriptor)

    def save():
        descriptor = os.open(result_path, os.O_WRONLY | os.O_TRUNC | os.O_NOFOLLOW)
        with os.fdopen(descriptor, 'w') as stream:
            json.dump(result, stream)
            stream.flush()
            os.fsync(stream.fileno())

    try:
        save()
        if args.execute:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY | os.O_NOFOLLOW, 0o600)
            with os.fdopen(descriptor, 'wb') as stream:
                stream.write(lock_bytes)
                lock_inode = os.fstat(stream.fileno()).st_ino
        result['checks'] = fresh_checks()
        require(hashlib.sha256(private_read(original_path)).hexdigest() == original_hash,
                "original release state changed during checks")
        if args.execute:
            require(lock.lstat().st_ino == lock_inode and lock.read_bytes() == lock_bytes,
                    "deployment actor lock changed")
            result['phase'] = 'normal-ingress-end'
            save()
            run(['python3', '-', 'end', SHA], INGRESS_SOURCE)
            result['normalIngressEndConfirmed'] = True
            result['phase'] = 'normal-durable-end'
            save()
            run(['docker', 'exec', 'yleum-prod-api', 'python', '-m',
                 'yleum_api.services.generation_deployment_drain', 'end', SHA])
            result['normalDurableEndConfirmed'] = True
            save()
            post = json.loads(run(['docker', 'exec', 'yleum-prod-api', 'python', '-m',
                                  'yleum_api.services.generation_deployment_drain', 'status', SHA]))
            require(post.get('release_sha') is None, "normal durable end did not clear fence")
            require(not Path('/var/lib/yleum/generation-ingress-drain/active.json').exists(),
                    "normal ingress end did not clear owned state")
            result['postDrainStatus'] = post
            result['postHealth'] = json.loads(api_python(HEALTH_PROGRAM))
            result['phase'] = 'normal-finalization-complete'
        else:
            result['phase'] = 'read-only-gates-passed'
    except Exception as error:
        result['failedPhase'] = result['phase']
        result['phase'] = 'blocked'
        result['errorType'] = type(error).__name__
        if isinstance(error, RuntimeError):
            result['guardFailure'] = str(error)
    finally:
        save()
        if lock_inode is not None and lock.exists() and lock.lstat().st_ino == lock_inode:
            require(lock.read_bytes() == lock_bytes, "actor lock modified; retained")
            lock.unlink()
    print(json.dumps({'candidate': SHA, 'phase': result['phase'], 'resultFile': str(result_path),
                      'originalCanonicalExitCode': 1}))
    return 1 if result['phase'] == 'blocked' else 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as error:
        # External response bodies, commands, environments and logs never print.
        print(json.dumps({'phase': 'blocked', 'errorType': type(error).__name__,
                          'originalCanonicalExitCode': 1}))
        raise SystemExit(1) from None
